import math
# convex polygon point containment via cross products

def convex_hull(points):
    pts=sorted(set(points))
    def cr(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in pts:
        while len(lo)>=2 and cr(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    hi=[]
    for p in reversed(pts):
        while len(hi)>=2 and cr(hi[-2],hi[-1],p)<=0: hi.pop()
        hi.append(p)
    return lo[:-1]+hi[:-1]
def inside_convex(pt, poly, strict=False):
    vals=[]
    for a,b in zip(poly,poly[1:]+poly[:1]):
        z=(b[0]-a[0])*(pt[1]-a[1])-(b[1]-a[1])*(pt[0]-a[0])
        vals.append(z)
    return all(v>1e-8 for v in vals) or all(v<-1e-8 for v in vals) if strict else (all(v>=-1e-8 for v in vals) or all(v<=1e-8 for v in vals))
